export interface FolderHealth { folder: string; score: number; openFindings: number }

export function folderHealth(folder: string, openFindings: number, notes: number): FolderHealth {
  const score = notes === 0 ? 100 : Math.max(0, Math.round(100 - (openFindings / notes) * 100));
  return { folder, score, openFindings };
}

