write.src/findings/lifecycle.ts:
export type FindingState = 'open' | 'acknowledged' | 'resolved';

const allowed: Record<FindingState, FindingState[]> = {
  open: ['acknowledged', 'resolved'],
  acknowledged: ['open', 'resolved'],
  resolved: ['open'],
};

export function transition(from: FindingState, to: FindingState): FindingState {
  if (!allowed[from].includes(to)) throw new Error(`invalid transition ${from} -> ${to}`);
  return to;
}

