write.src/knowledge/orphans.ts:
export function orphanClusters(edges: Array<[string, string]>, notes: string[]): string[][] {
  const linked = new Set(edges.flat());
  return notes.filter((n) => !linked.has(n)).map((n) => [n]);
}

write.src/knowledge/links.ts:
export function staleLinks(links: Array<{ from: string; to: string }>, existing: Set<string>) {
  return links.filter((l) => !existing.has(l.to));
}

